// GENERATED by scripts/bundle-cardboard-flip.mjs — do not edit. Edit js/*.js and re-run.
// ── market.js ──
// market.js — seeded market + rumor engine.
//
// How prices work (one sentence): every product has a hidden TRUE VALUE that
// drifts a little each day, events bend that value up or down on a fixed
// shape, and each store quotes true value x its own markup x a little noise.
//
//   price(store, product, day) = trueValue(product, day) x store.markup x noise
//   trueValue(product, day)    = baseline(day) x product of active event curves
//
// Events are planned for all 30 days at game start from the seed, so the same
// seed always produces the same market (daily challenges, challenge links).
// Rumors show up 1-3 days BEFORE an event starts. Some rumors are fake.
//
// Event shapes (multipliers on true value, by days since the event starts):
//   HYPE     quick spike (~+130% on day 2), then craters below where it started,
//            then recovers. Sell the peak; don't be holding on day 4.
//   OOP      out of print: roughly doubles over 3 days and STAYS up forever.
//   REPRINT  dips ~35%, shelves flood, recovers only part of the way.
//
// The TCG Convention is the swingiest venue: widest daily noise, it overreacts to
// events, and its crowd moves on rumors (even fake ones) before anything is confirmed.
//
//   CRUNCH   short supply crunch: shelves go thin, price +35-45% for a few days.

(function (root) {
  "use strict";

  // ---------------------------------------------------------------------------
  // Tuning knobs — everything a designer should touch lives here.
  // ---------------------------------------------------------------------------
  const DAYS = 30;       // main game
  const HORIZON = 120;   // market keeps running for the post-game Grail hunt

  const PRODUCTS = [
    { name: "The Base Set",          tier: "vintage", start: 600 },
    { name: "The Nostalgia Set",     tier: "vintage", start: 520 },
    { name: "Dark Flames",           tier: "mid",     start: 165 },
    { name: "Masks of Dawn",         tier: "mid",     start: 140 },
    { name: "Prizms of Change",      tier: "modern",  start: 215 },
    { name: "Inevitable Opponents",  tier: "modern",  start: 190 }
  ];

  // drift = average daily change in baseline; vol = daily wobble
  // volGrowth: how much the daily wobble grows as the market matures.
  // Vintage starts calm and gets wild: by Day 30 its wobble is 1 + volGrowth times bigger.
  // rumorWeight: how often events and rumors land on this tier.
  const TIERS = {
    vintage: { drift: 0.005,  vol: 0.015, volGrowth: 3.0, rumorWeight: 1 }, // the high end: calm early, volatile late
    mid:     { drift: 0.0,    vol: 0.03,  volGrowth: 0,   rumorWeight: 3 },
    modern:  { drift: -0.002, vol: 0.04,  volGrowth: 0,   rumorWeight: 3 }  // low end: where the rumors hit
  };
  const volOn = (tier, d) => tier.vol * (1 + tier.volGrowth * Math.min(d, DAYS) / DAYS);

  // markup: multiplier on true value (a number, or one per tier). noise: +/- daily wiggle.
  // stock: [min, max] boxes per product per day (buy side).
  // depth: sell side only — each box you sell here today knocks the price down.
  // openDays: optional — which days a location is open (day 1 = Monday).
  const weekends = d => d % 7 === 6 || d % 7 === 0;
  const LOCATIONS = {
    "Local Game Store": { side: "buy",  markup: 1.00, noise: 0.03, stock: [8, 12] },
    "Cost-Mart":        { side: "buy",  markup: 0.93, noise: 0.04, stock: [1, 4] },
    "eCommerce Store":  { side: "buy",  markup: 0.92, noise: 0.12, stock: [0, 14], shipDays: 3 },
    // Sell spots pay by tier: lower-end boxes flip for a small profit over
    // retail; vintage only pays when the market moves your way.
    "The Marketplace":  { side: "sell", markup: { vintage: 0.93, mid: 1.04, modern: 1.04 }, noise: 0.04, depth: 0.004 },
    "TCG Convention":   { side: "sell", markup: { vintage: 0.97, mid: 1.00, modern: 1.00 }, noise: 0.10, depth: 0.02, openDays: weekends, crowd: true }
  };

  // The Convention crowd trades on news: it overreacts to confirmed events
  // (eventAmp stretches each event's curve) and moves on RUMORS before anything
  // is confirmed (rumorReact, from the rumor day until the event starts or the
  // rumor is debunked) — fake ones included. Leakers move the crowd more than creators.
  const CROWD = {
    eventAmp:   { oop: 1.9, reprint: 1.9, crunch: 1.4, hype: 1.2 },
    rumorReact: { oop: 0.32, reprint: -0.3, crunch: 0.15, hype: 0.1 },
    sourceWeight: { leaker: 1, creator: 0.7 }
  };

  // Online listings: chance EACH listed box sells per day, based on how far
  // your ask is above true value. Sellers pay a platform fee.
  const LISTING = { fee: 0.13, atValue: 0.7, perTenPctOver: 0.22, min: 0.02 };

  // Event shapes: [daysSinceStart, multiplier] keyframes, linearly interpolated.
  // The LAST keyframe holds forever, which is how permanent moves work.
  // magnitude jitter scales each curve's distance from 1.0.
  const EVENTS = {
    hype: {
      price:  [[0, 1], [1, 1.6], [2, 2.3], [3, 1.4], [4, 0.65], [6, 0.8], [9, 1]],
      supply: [[0, 1], [1, 0.6], [2, 0.5], [4, 1.5], [7, 1]],
      magnitude: [0.8, 1.2]
    },
    oop: {
      price:  [[0, 1], [1, 1.35], [3, 2.1]],
      supply: [[0, 1], [1, 0.5], [3, 0.35]],
      magnitude: [0.8, 1.3]
    },
    reprint: {
      price:  [[0, 1], [2, 0.65], [10, 0.85]],
      supply: [[0, 1], [1, 3], [8, 1.4]],
      magnitude: [0.8, 1.2]
    },
    crunch: {
      price:  [[0, 1], [1, 1.35], [3, 1.45], [5, 1]],
      supply: [[0, 1], [1, 0.3], [3, 0.3], [5, 1]],
      magnitude: [0.8, 1.2]
    }
  };

  // How many events per run, and how rumors are sourced.
  const PLAN = {
    realEvents: 9,
    fakeRumors: 3,
    weights: { hype: 3, oop: 2, reprint: 2, crunch: 2 },
    startDays: [4, 26],       // earliest/latest an event can begin
    leadDays: [2, 4],         // rumor appears this many days before
    sameProductGap: 7,        // min days between events on one product
    // who reports real vs fake rumors. Leakers are right ~90% of the time,
    // creators ~60%. Players learn to weigh the source.
    leakerShareOfReal: 0.6,
    leakerShareOfFake: 0.15
  };

  const HEADLINES = {
    rumor: {
      hype: {
        leaker:  p => `🔎 LEAKER: A mega-streamer is opening a case of ${p} live this week.`,
        creator: p => `📣 CREATOR: ${p} is about to go CRAZY. Trust me.`
      },
      oop: {
        leaker:  p => `🔎 LEAKER: Distributor emails say ${p} is getting its final print run.`,
        creator: p => `📣 CREATOR: I'm hearing ${p} is going out of print!!`
      },
      reprint: {
        leaker:  p => `🔎 LEAKER: A shipping manifest shows a huge reprint of ${p}.`,
        creator: p => `📣 CREATOR: ${p} reprint incoming? Don't get stuck holding.`
      },
      crunch: {
        leaker:  p => `🔎 LEAKER: Distributors are short on ${p} this week.`,
        creator: p => `📣 CREATOR: ${p} is about to be impossible to find.`
      }
    },
    start: {
      hype:    p => `📰 NEWS: ${p} got opened live to 2M viewers. Buyers are going wild.`,
      oop:     p => `📰 CONFIRMED: ${p} is officially out of print.`,
      reprint: p => `📰 NEWS: Reprints of ${p} are hitting shelves everywhere.`,
      crunch:  p => `📰 NEWS: ${p} shipments are delayed. Shelves are bare.`
    },
    followUp: {
      hype:   { day: 3, text: p => `📉 Hype on ${p} is fading. Sellers are dumping.` },
      crunch: { day: 4, text: p => `📦 ${p} shipments are back on track.` }
    },
    debunk: p => `🧢 That ${p} rumor? Total cap. Nothing happened.`,
    quiet: "No news today..."
  };

  // ---------------------------------------------------------------------------
  // Seeded RNG (mulberry32) — tiny, fast, good enough for games.
  // ---------------------------------------------------------------------------
  function hashSeed(str) {
    let h = 1779033703 ^ str.length;
    for (let i = 0; i < str.length; i++) {
      h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
      h = (h << 13) | (h >>> 19);
    }
    return () => {
      h = Math.imul(h ^ (h >>> 16), 2246822507);
      h = Math.imul(h ^ (h >>> 13), 3266489909);
      return (h ^= h >>> 16) >>> 0;
    };
  }
  function makeRng(seed) {
    let a = hashSeed(String(seed))();
    const next = () => {
      a |= 0; a = (a + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    return {
      next,
      range: (lo, hi) => lo + next() * (hi - lo),
      int: (lo, hi) => lo + Math.floor(next() * (hi - lo + 1)),
      pick: arr => arr[Math.floor(next() * arr.length)],
      gauss: () => { // Box-Muller
        const u = Math.max(next(), 1e-9), v = next();
        return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
      },
      weighted: w => {
        const total = Object.values(w).reduce((a, b) => a + b, 0);
        let x = next() * total;
        for (const [k, v] of Object.entries(w)) { if ((x -= v) < 0) return k; }
        return Object.keys(w)[0];
      }
    };
  }

  function curveAt(keys, t, mag) {
    if (t < 0) return 1;
    let m = keys[keys.length - 1][1];
    for (let i = 0; i < keys.length - 1; i++) {
      const [t0, v0] = keys[i], [t1, v1] = keys[i + 1];
      if (t >= t0 && t <= t1) { m = v0 + ((t - t0) / (t1 - t0)) * (v1 - v0); break; }
    }
    return 1 + (m - 1) * mag;
  }

  // ---------------------------------------------------------------------------
  // Plan the whole run up front from the seed.
  // ---------------------------------------------------------------------------
  function planRun(seed) {
    const rng = makeRng(seed + "|plan");
    const names = PRODUCTS.map(p => p.name);
    const productWeights = {};
    PRODUCTS.forEach(p => (productWeights[p.name] = TIERS[p.tier].rumorWeight));
    const events = [];

    const blocks = Math.ceil(HORIZON / DAYS);
    let guard = 0;
    while (events.length < PLAN.realEvents * blocks && guard++ < 2000) {
      const block = Math.floor(events.length / PLAN.realEvents) * DAYS;
      const type = rng.weighted(PLAN.weights);
      const product = rng.weighted(productWeights);
      const start = block + rng.int(PLAN.startDays[0], PLAN.startDays[1]);
      const clash = events.some(e => e.product === product && Math.abs(e.start - start) < PLAN.sameProductGap);
      if (clash) continue;
      const lead = rng.int(PLAN.leadDays[0], PLAN.leadDays[1]);
      events.push({
        type, product, start,
        rumorDay: Math.max(2, start - lead),
        source: rng.next() < PLAN.leakerShareOfReal ? "leaker" : "creator",
        mag: rng.range(EVENTS[type].magnitude[0], EVENTS[type].magnitude[1]),
        fake: false
      });
    }
    const fakes = [];
    guard = 0;
    while (fakes.length < PLAN.fakeRumors * blocks && guard++ < 2000) {
      const block = Math.floor(fakes.length / PLAN.fakeRumors) * DAYS;
      const type = rng.weighted(PLAN.weights);
      const product = rng.weighted(productWeights);
      const rumorDay = block + rng.int(2, DAYS - 3);
      const clash = events.concat(fakes).some(e => e.product === product && Math.abs(e.rumorDay - rumorDay) < 4);
      if (clash) continue;
      fakes.push({
        type, product, rumorDay, start: null,
        source: rng.next() < PLAN.leakerShareOfFake ? "leaker" : "creator",
        fake: true
      });
    }
    return { events, fakes };
  }

  // Precompute every day's true value, quotes and stock so the market is
  // identical for everyone on the same seed, no matter what they do.
  function buildSeries(seed, plan, opts) {
    const rng = makeRng(seed + "|series");
    const series = {}; // series[product] = { base[], value[], supply[] }
    PRODUCTS.forEach(p => {
      const t = TIERS[p.tier];
      const base = [p.start];
      for (let d = 1; d <= HORIZON; d++) {
        base.push(base[d - 1] * (1 + t.drift + volOn(t, d) * rng.gauss()));
      }
      const value = [], supply = [], crowd = [];
      const mine = plan.events.filter(e => e.product === p.name);
      const rumors = plan.events.concat(plan.fakes).filter(e => e.product === p.name);
      for (let d = 0; d <= HORIZON; d++) {
        let pm = 1, sm = 1, cm = 1;
        mine.forEach(e => {
          pm *= curveAt(EVENTS[e.type].price, d - e.start, e.mag);
          sm *= curveAt(EVENTS[e.type].supply, d - e.start, 1);
          cm *= curveAt(EVENTS[e.type].price, d - e.start, e.mag * CROWD.eventAmp[e.type]);
        });
        rumors.forEach(e => {
          const until = e.fake ? e.rumorDay + 3 : e.start;
          if (d >= e.rumorDay && d < until) cm *= 1 + CROWD.rumorReact[e.type] * CROWD.sourceWeight[e.source];
        });
        value.push(base[d] * pm);
        supply.push(sm);
        crowd.push(pm > 0 ? cm / pm : 1); // Convention price relative to true value
      }
      series[p.name] = { base, value, supply, crowd };
    });

    const quotes = {}; // quotes[day][loc][product] = { price, stock }
    const mystery = {}; // mystery[day][loc] = price, if a store has a mystery box that day
    const mrng = makeRng(seed + "|mystery");
    for (let d = 0; d <= HORIZON; d++) {
      quotes[d] = {};
      mystery[d] = {};
      Object.entries(LOCATIONS).forEach(([loc, L]) => {
        quotes[d][loc] = {};
        PRODUCTS.forEach(p => {
          const v = series[p.name].value[d] * (L.crowd ? series[p.name].crowd[d] : 1);
          const mk = typeof L.markup === "number" ? L.markup : L.markup[p.tier];
          const price = Math.max(5, Math.round(v * mk * (1 + L.noise * (rng.next() * 2 - 1))));
          let stock = null;
          if (L.side === "buy") {
            stock = Math.max(0, Math.round(rng.int(L.stock[0], L.stock[1]) * series[p.name].supply[d]));
          }
          quotes[d][loc][p.name] = { price, stock };
        });
        if (L.side === "buy" && opts.mysteryChance && mrng.next() < opts.mysteryChance) {
          const [lo, hi] = opts.mysteryPrice || [120, 220];
          mystery[d][loc] = Math.round(lo + mrng.next() * (hi - lo));
        }
      });
    }
    return { series, quotes, mystery };
  }

  function headlinesFor(day, plan) {
    const out = [];
    plan.events.concat(plan.fakes).forEach(e => {
      if (e.rumorDay === day) out.push(HEADLINES.rumor[e.type][e.source](e.product));
    });
    plan.events.forEach(e => {
      if (e.start === day) out.push(HEADLINES.start[e.type](e.product));
      const f = HEADLINES.followUp[e.type];
      if (f && e.start + f.day === day) out.push(f.text(e.product));
    });
    plan.fakes.forEach(e => { if (e.rumorDay + 3 === day) out.push(HEADLINES.debunk(e.product)); });
    return out;
  }

  // ---------------------------------------------------------------------------
  // Public market object
  // ---------------------------------------------------------------------------
  // opts: { mysteryChance, mysteryPrice } — mystery box days (seeded, so
  // everyone on the same seed sees the same boxes; contents are per player).
  function create(seed, opts = {}) {
    seed = seed == null ? String(Math.floor(Math.random() * 1e9)) : String(seed);
    const plan = planRun(seed);
    const { series, quotes, mystery } = buildSeries(seed, plan, opts);
    const mysteryTaken = {};
    const listingRng = makeRng(seed + "|listings");

    let day = 1;
    let bought = {};   // bought[loc][product] = boxes bought here today
    let sold = {};     // sold[loc][product]   = boxes sold here today
    let cleared = {};  // cleared[loc][product] = true if sold out mid-day
    const resetDay = () => { bought = {}; sold = {}; cleared = {}; };
    const bump = (obj, loc, p) => { (obj[loc] = obj[loc] || {}); obj[loc][p] = (obj[loc][p] || 0) + 1; };
    const get = (obj, loc, p) => (obj[loc] && obj[loc][p]) || 0;

    const m = {
      seed,
      DAYS,
      HORIZON,
      products: PRODUCTS.map(p => p.name),
      buyLocations: Object.keys(LOCATIONS).filter(l => LOCATIONS[l].side === "buy"),
      sellLocations: Object.keys(LOCATIONS).filter(l => LOCATIONS[l].side === "sell"),
      get day() { return day; },

      // Price at a store right now. Sell prices drop as you dump boxes there.
      isOpen(loc) { const f = LOCATIONS[loc].openDays; return !f || f(day); },

      price(loc, p) {
        if (!m.isOpen(loc)) return null;
        const q = quotes[day][loc][p].price;
        const L = LOCATIONS[loc];
        if (L.side === "sell") return Math.max(5, Math.round(q * Math.pow(1 - L.depth, get(sold, loc, p))));
        return q;
      },
      stock(loc, p) {
        const L = LOCATIONS[loc];
        if (L.side !== "buy") return Infinity;
        if (cleared[loc] && cleared[loc][p]) return 0;
        return Math.max(0, quotes[day][loc][p].stock - get(bought, loc, p));
      },
      shipDays(loc) { return LOCATIONS[loc].shipDays || 0; },

      buy(loc, p) {
        if (LOCATIONS[loc].side !== "buy" || !m.isOpen(loc) || m.stock(loc, p) <= 0) return { ok: false };
        const price = m.price(loc, p);
        bump(bought, loc, p);
        return { ok: true, price, arrivesDay: day + m.shipDays(loc) };
      },
      sell(loc, p) {
        if (LOCATIONS[loc].side !== "sell" || !m.isOpen(loc)) return { ok: false };
        const price = m.price(loc, p);
        bump(sold, loc, p);
        return { ok: true, price };
      },
      // For the 2-minute sellout clock: wipe a product off a shelf for today.
      sellOut(loc, p) { (cleared[loc] = cleared[loc] || {})[p] = true; },

      // Online listing: returns how many of the listed boxes sold today, and
      // the payout per box after fees.
      // cfg lets other venues (your own shop shelves) use different odds/fees.
      listingSales(p, askPrice, qty, cfg = LISTING) {
        const ratio = askPrice / series[p].value[day];
        const chance = Math.max(cfg.min,
          Math.min(0.95, cfg.atValue - Math.max(0, ratio - 1) * 10 * cfg.perTenPctOver));
        let n = 0;
        for (let i = 0; i < qty; i++) if (listingRng.next() < chance) n++;
        return { sold: n, payoutEach: askPrice * (1 - cfg.fee), chance };
      },

      headlines() { return headlinesFor(day, plan); },

      // Mystery box at this store today? Returns price or null. One per store per day.
      mysteryBox(loc) {
        const pr = mystery[day] && mystery[day][loc];
        return pr && !mysteryTaken[day + loc] ? pr : null;
      },
      takeMysteryBox(loc) {
        const pr = m.mysteryBox(loc);
        if (!pr) return null;
        mysteryTaken[day + loc] = true;
        return pr;
      },
      // Today's true value (for ripping cash-back and end-of-run net worth).
      valueNow(p) { return series[p].value[day]; },

      // Sim bots stop at the main-game end; the real game keeps going for the post-game.
      nextDay(limit = HORIZON) {
        if (day >= limit) return false;
        day++;
        resetDay();
        return true;
      },

      // For end-of-game share cards / charts. Hidden during play.
      valueHistory(p) { return series[p].value.slice(1, day + 1).map(v => Math.round(v)); },
      // Debug/tuning only — reveals the plan. Don't show players.
      _plan: plan,
      _series: series
    };
    return m;
  }

  const api = { create, PRODUCTS, LOCATIONS, EVENTS, TIERS, PLAN, LISTING, curveAt, DAYS, HORIZON };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  root.TCGMarket = api;
})(typeof window !== "undefined" ? window : globalThis);
;

// ── rules.js ──
// rules.js — rent, debt, shop goal, ripping and Grail odds.
// Shared by the game (js/game.js) and the balance simulator (tools/simulate.js).
// Every number a designer might tune lives in RULES.

(function (root) {
  "use strict";

  const RULES = {
    startCash: 1500,
    mainDays: 30,          // the main game: open your shop before this ends
    maxDays: 120,          // hard stop for the post-game Grail hunt

    // Rent is due every 7 days. Can't cover it? The shortfall becomes debt.
    rentEvery: 7,
    rent: [450],           // flat $450 every 7 days (sim: casual players break even, skilled shop day unchanged)
    rentStepAfter: 0,

    // Debt / loan shark
    debtRate: 0.05,        // 5% per day, compounding
    borrowLimit: 5000,     // max you can voluntarily borrow (total debt)
    evictAt: 10000,        // debt past this = evicted, run over

    // Shop goal
    lease: 12000,          // cash needed to open your card shop (sim: strong players ~Day 20, flip-only ~Day 27)
    shopIncome: [40, 120],  // daily walk-in sales (singles, sleeves) once open; rent stops once you own the shop
    // Your shop's shelves: boxes you stock and price yourself. No platform fee,
    // better odds than online. Chance per box per day = atValue at/below value,
    // minus perTenPctOver for every 10% your price is above value.
    shelf: { fee: 0, atValue: 0.8, perTenPctOver: 0.2, min: 0.02 },

    // Ripping sealed boxes you own. Cash back comes from selling the singles.
    // Each row: [chance, minMultiple, maxMultiple] of what you paid.
    rip: [
      [0.60, 0.20, 0.55],   // bricked
      [0.28, 0.60, 1.10],   // decent
      [0.10, 1.10, 2.20],   // nice hits
      [0.02, 3.00, 6.00]    // monster box
    ],
    grailDollarsPerPercent: 500, // Grail odds per box = box value / (this x 100). $200 box ≈ 1 in 250
    godPackChance: 1 / 50,       // per box ripped
    godPackCashBack: [3, 5],     // god pack pays this multiple of the box
    godPackGrailBoost: 15,       // and multiplies that box's Grail odds

    // Mystery boxes: sometimes a store has one unlabeled box.
    mysteryChancePerDay: 0.35,   // chance a given buy store has one today
    mysteryPrice: [120, 220],
    mystery: [
      // [chance, outcome, minMultiple, maxMultiple]
      [0.60, "junk",   0.15, 0.50],
      [0.30, "decent", 0.80, 1.60],
      [0.08, "big",    3.00, 6.00],
      [0.019, "god",   0, 0],     // a god pack: big cash back + boosted Grail odds
      [0.001, "grail", 0, 0]      // THE GRAIL, straight out of the box
    ],

    grailName: "THE GRAIL"
  };

  function rentForWeek(week) {
    if (week <= RULES.rent.length) return RULES.rent[week - 1];
    return RULES.rent[RULES.rent.length - 1] + (week - RULES.rent.length) * RULES.rentStepAfter;
  }
  function rentDue(day) {
    return day % RULES.rentEvery === 0 ? rentForWeek(day / RULES.rentEvery) : 0;
  }
  function nextRent(day) {
    const d = Math.floor(day / RULES.rentEvery + 1) * RULES.rentEvery;
    return { day: d, amount: rentForWeek(d / RULES.rentEvery) };
  }

  const pickRow = (rows, r) => {
    let acc = 0;
    for (const row of rows) { acc += row[0]; if (r < acc) return row; }
    return rows[rows.length - 1];
  };

  // Rip one box. value = what the box is worth today (drives cash back + odds).
  // rand() should be per-player (Math.random), not the market seed.
  function ripBox(value, rand = Math.random, grailBoost = 1) {
    const god = rand() < RULES.godPackChance;
    let cashBack;
    if (god) {
      cashBack = value * (RULES.godPackCashBack[0] + rand() * (RULES.godPackCashBack[1] - RULES.godPackCashBack[0]));
    } else {
      const row = pickRow(RULES.rip, rand());
      cashBack = value * (row[1] + rand() * (row[2] - row[1]));
    }
    const odds = Math.min(0.5, (value / (RULES.grailDollarsPerPercent * 100)) * (god ? RULES.godPackGrailBoost : 1) * grailBoost);
    const grail = rand() < odds;
    return { cashBack: Math.round(cashBack), god, grail, odds };
  }

  function openMystery(price, rand = Math.random) {
    const row = pickRow(RULES.mystery, rand());
    const outcome = row[1];
    if (outcome === "grail") return { outcome, cashBack: 0, grail: true, god: false };
    if (outcome === "god") {
      const g = RULES.godPackCashBack;
      const odds = Math.min(0.5, (price / (RULES.grailDollarsPerPercent * 100)) * RULES.godPackGrailBoost);
      return { outcome, cashBack: Math.round(price * (g[0] + rand() * (g[1] - g[0]))), grail: rand() < odds, god: true };
    }
    return { outcome, cashBack: Math.round(price * (row[2] + rand() * (row[3] - row[2]))), grail: false, god: false };
  }

  function rankFor(r) {
    // r: { evicted, shopDay, grailBox, netWorth }
    if (r.evicted) return "EVICTED";
    if (r.shopDay && r.grailBox) return "GRAIL KEEPER";
    if (r.shopDay) return "CARD SHOP OWNER";
    if (r.netWorth >= RULES.lease * 0.6) return "TABLE VENDOR";
    if (r.netWorth >= RULES.startCash * 2) return "WEEKEND FLIPPER";
    return "COUCH FLIPPER";
  }

  const api = { RULES, rentDue, nextRent, rentForWeek, ripBox, openMystery, rankFor };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  root.TCGRules = api;
})(typeof window !== "undefined" ? window : globalThis);
;

// ── intro.js ──
// intro.js — 16-bit arcade-style intro cut scene + first-run tutorial.
//
// Flow: TAP TO START -> cut scene (7 scenes) -> title screen -> tutorial -> game.
//
// Text only: each scene has a short "place" slug shown above the dialog
// instead of artwork. Edit the SCENES array to change any line.

(function () {
  "use strict";

  const SEEN_KEY = "tcgscalper.seenIntro";
  const MUTE_KEY = "tcgscalper.muted";

  // ---------------------------------------------------------------------------
  // Script
  // ---------------------------------------------------------------------------
  // who: speaker tag (omit for narration).
  // sfx: "rip" | "ding" | "bulb" sound played when the line starts.
  const SCENES = [
    {
      place: "HEAT KICKS SNEAKERS — 11:47 PM",
      lines: [
        { t: "HEAT KICKS — the last sneaker spot on the block — is closing for good." },
        { who: "YOU", t: "Now that sneaker resale is dead... how will I pay my bills?" }
      ]
    },
    {
      place: "THE STREET OUTSIDE",
      lines: [
        { t: "Across the street, a neon sign buzzes to life..." },
        { who: "YOU", t: "\"Trading cards for sale\"...? Huh." }
      ]
    },
    {
      place: "THE CARD SHOP",
      lines: [
        { who: "SHOP OWNER", t: "Welcome in! Packs are five bucks. Feeling lucky?" },
        { who: "YOU", t: "Eh... why not. Gimme one." }
      ]
    },
    {
      place: "THE CARD SHOP",
      lines: [
        { t: "*RIIIIIP*", sfx: "rip" }
      ]
    },
    {
      place: "THE CARD SHOP",
      lines: [
        { t: "A foil glint flashes through the pack...", sfx: "ding" },
        { who: "YOU", t: "Whoa. Is that... a hit?" }
      ]
    },
    {
      place: "THE CARD SHOP — COUNTER",
      lines: [
        { who: "SHOP OWNER", t: "Nice pull! We sell that exact card for $100 in the case." },
        { who: "YOU", t: "A HUNDRED?! I paid five bucks for the pack!" }
      ]
    },
    {
      place: "THE CARD SHOP — COUNTER",
      lines: [
        { t: "*DING*", sfx: "bulb" },
        { who: "YOU", t: "Buy low. Sell high. I already know this game..." }
      ]
    }
  ];

  // ---------------------------------------------------------------------------
  // Chiptune-ish sound (WebAudio, no files)
  // ---------------------------------------------------------------------------
  let ctx = null;
  let muted = false;
  try { muted = localStorage.getItem(MUTE_KEY) === "1"; } catch (e) {}

  function audio() {
    if (!ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (AC) ctx = new AC();
    }
    if (ctx && ctx.state === "suspended") ctx.resume();
    return ctx;
  }
  function tone(freq, dur, type = "square", vol = 0.05, when = 0) {
    if (muted || !audio()) return;
    const t = ctx.currentTime + when;
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(ctx.destination);
    o.start(t); o.stop(t + dur);
  }
  function noise(dur, vol = 0.12) {
    if (muted || !audio()) return;
    const len = Math.floor(ctx.sampleRate * dur);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate), data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = ctx.createBufferSource(), g = ctx.createGain();
    src.buffer = buf; g.gain.value = vol;
    src.connect(g).connect(ctx.destination); src.start();
  }
  const SFX = {
    blip: () => tone(660, 0.04, "square", 0.025),
    rip: () => noise(0.5),
    ding: () => { tone(988, 0.15); tone(1319, 0.3, "square", 0.05, 0.12); },
    bulb: () => [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.18, "square", 0.05, i * 0.09)),
    start: () => [392, 523, 659, 784, 1047].forEach((f, i) => tone(f, 0.12, "square", 0.05, i * 0.07)),
    select: () => tone(880, 0.06, "square", 0.04)
  };

  // ---------------------------------------------------------------------------
  // Cut scene engine
  // ---------------------------------------------------------------------------
  function el(tag, attrs = {}, html = "") {
    const e = document.createElement(tag);
    Object.entries(attrs).forEach(([k, v]) => e.setAttribute(k, v));
    e.innerHTML = html;
    return e;
  }

  function runCutscene() {
    return new Promise(resolve => {
      const overlay = el("div", { id: "intro-overlay", role: "dialog", "aria-label": "Intro" });
      const stage = el("div", { id: "intro-stage" });
      const place = el("div", { id: "intro-place" });
      const dialog = el("div", { id: "intro-dialog" },
        '<div id="intro-speaker"></div><div id="intro-text"></div><div id="intro-next">▼</div>');
      const fader = el("div", { id: "intro-fader" });
      const skip = el("button", { id: "intro-skip", class: "intro-ctrl", type: "button" }, "SKIP ▶▶");
      const mute = el("button", { id: "intro-mute", class: "intro-ctrl", type: "button" }, muted ? "♪ OFF" : "♪ ON");
      stage.append(place, dialog, fader, skip, mute);
      overlay.append(stage);
      document.body.append(overlay);
      document.body.style.overflow = "hidden";

      const speakerEl = dialog.querySelector("#intro-speaker");
      const textEl = dialog.querySelector("#intro-text");
      const nextEl = dialog.querySelector("#intro-next");

      let mode = "attract"; // attract -> scene -> title -> done
      let sceneIdx = 0, lineIdx = 0;
      let typing = null, fullText = "", busy = false;

      function showScreen(html) {
        stage.querySelectorAll(".intro-screen").forEach(n => n.remove());
        const s = el("div", { class: "intro-screen" }, html);
        stage.append(s);
        return s;
      }

      function attract() {
        dialog.style.display = "none";
        place.textContent = "";
        showScreen(`
          <div class="intro-sub">JAWNPACK PRESENTS</div>
          <div class="intro-press blink">TAP TO START</div>
          <div class="intro-small">© 2026</div>`);
      }

      function loadScene(i) {
        place.textContent = SCENES[i].place || "";
      }

      function typeLine() {
        const line = SCENES[sceneIdx].lines[lineIdx];
        speakerEl.textContent = line.who || "";
        textEl.className = line.who ? "" : "narration";
        fullText = line.t;
        textEl.textContent = "";
        nextEl.style.visibility = "hidden";
        if (line.sfx) SFX[line.sfx]();
        let n = 0;
        clearInterval(typing);
        typing = setInterval(() => {
          n++;
          textEl.textContent = fullText.slice(0, n);
          if (n % 2 === 0 && fullText[n - 1] !== " ") SFX.blip();
          if (n >= fullText.length) finishTyping();
        }, 32);
      }
      function finishTyping() {
        clearInterval(typing); typing = null;
        textEl.textContent = fullText;
        nextEl.style.visibility = "visible";
      }

      function fadeThen(fn) {
        busy = true;
        fader.classList.add("on");
        setTimeout(() => { fn(); fader.classList.remove("on"); setTimeout(() => (busy = false), 350); }, 380);
      }

      function startScenes() {
        mode = "scene";
        SFX.start();
        fadeThen(() => {
          stage.querySelectorAll(".intro-screen").forEach(n => n.remove());
          dialog.style.display = "";
          sceneIdx = 0; lineIdx = 0;
          loadScene(0);
          typeLine();
        });
      }

      function title() {
        mode = "title";
        clearInterval(typing);
        fadeThen(() => {
          dialog.style.display = "none";
          place.textContent = "";
          skip.style.display = "none";
          const s = showScreen(`
            <div class="intro-title">THE CARDBOARD<br>FLIP</div>
            <div class="intro-sub">$1,500. 30 DAYS. OPEN YOUR SHOP.</div>
            <div class="intro-menu">
              <button type="button" data-choice="tutorial">HOW TO PLAY</button>
              <button type="button" data-choice="play">JUMP RIGHT IN</button>
            </div>`);
          SFX.bulb();
          const first = s.querySelector("button");
          setTimeout(() => first && first.focus(), 850);
          s.querySelectorAll("button").forEach(b =>
            b.addEventListener("click", ev => {
              ev.stopPropagation();
              SFX.select();
              finish(b.dataset.choice === "tutorial");
            }));
        });
      }

      function advance() {
        if (busy) return;
        if (mode === "attract") return startScenes();
        if (mode !== "scene") return;
        if (typing) return finishTyping();
        const sc = SCENES[sceneIdx];
        if (lineIdx < sc.lines.length - 1) { lineIdx++; return typeLine(); }
        if (sceneIdx < SCENES.length - 1) {
          fadeThen(() => { sceneIdx++; lineIdx = 0; loadScene(sceneIdx); typeLine(); });
          return;
        }
        title();
      }

      function onKey(e) {
        if (mode === "title") return; // menu buttons handle their own keys
        if (e.key === "Escape") { e.preventDefault(); if (mode === "scene") title(); return; }
        if ([" ", "Enter", "ArrowRight"].includes(e.key)) { e.preventDefault(); advance(); }
      }

      function finish(wantsTutorial) {
        mode = "done";
        clearInterval(typing);
        document.removeEventListener("keydown", onKey);
        try { localStorage.setItem(SEEN_KEY, "1"); } catch (e) {}
        fader.classList.add("on");
        setTimeout(() => {
          overlay.remove();
          document.body.style.overflow = "";
          resolve({ tutorial: wantsTutorial });
        }, 400);
      }

      overlay.addEventListener("click", advance);
      document.addEventListener("keydown", onKey);
      skip.addEventListener("click", e => { e.stopPropagation(); audio(); title(); });
      mute.addEventListener("click", e => {
        e.stopPropagation();
        muted = !muted;
        mute.textContent = muted ? "♪ OFF" : "♪ ON";
        try { localStorage.setItem(MUTE_KEY, muted ? "1" : "0"); } catch (err) {}
      });

      attract();
    });
  }

  // ---------------------------------------------------------------------------
  // Tutorial (coach marks over the real game UI)
  // ---------------------------------------------------------------------------
  const TUTORIAL = [
    { target: null,
      t: "Listen up, rookie. You've got $1,500 and 30 days to raise $12,000 and open your OWN card shop. Do it fast. The day you open is your score." },
    { target: "#topbar",
      t: "The day and your cash. Every day you can visit as many places as you like. Nothing moves until you hit NEXT DAY." },
    { target: "#tb-more",
      t: "Tap MORE for everything else: your boxes, debt, rent and the shop goal. RIP a box there for a shot at THE GRAIL." },
    { target: () => document.querySelectorAll(".places-group")[0],
      t: "BUY spots. Tap one to go there. Game Store = steady. Cost-Mart = cheaper, thin shelves. eComm = wild prices, ships in 3 days." },
    { target: "#counter",
      t: "The counter shows where you're standing. BUY one or MAX. At sell spots it's SELL or ALL. Mystery boxes show up here too." },
    { target: () => document.querySelectorAll(".places-group")[1],
      t: "SELL spots. Marketplace pays every day. The Convention (Sat & Sun) swings the hardest: the crowd goes wild on out-of-print and reprint news, even rumors. Online lets you set your own price. Your Shop unlocks when you open it." },
    { target: "#feed",
      t: "The Feed. Rumors hit a day or three before the market moves. LEAKERS are usually right. CREATORS... are creators. Some rumors are pure cap." },
    { target: "#tb-more",
      t: "Rent is $450, due every 7 days. Come up short and the loan shark covers it at 5% a DAY. You can borrow on purpose to go big on a hot tip. Owe $10K and you're evicted." },
    { target: "#next-day",
      t: "Done for the day? Hit NEXT DAY." },
    { target: null,
      t: "Open your shop and the game keeps going: rent stops, you stock your own shelves, and you hunt THE GRAIL. Watch for mystery boxes and god packs." },
    { target: null, last: true,
      t: "That's the game. Buy low. Sell high. Don't go broke. Let's see what you've got." }
  ];

  function runTutorial() {
    return new Promise(resolve => {
      const shield = el("div", { id: "tut-shield" });
      const spot = el("div", { id: "tut-spot" });
      const box = el("div", { id: "tut-box", role: "dialog", "aria-live": "polite" });
      document.body.append(shield, spot, box);
      let i = 0;

      function resolveTarget(t) {
        if (!t) return null;
        return typeof t === "function" ? t() : document.querySelector(t);
      }

      function show() {
        const step = TUTORIAL[i];
        const target = resolveTarget(step.target);
        box.innerHTML = `
          <div class="tut-who">SHOP OWNER</div>
          <div class="tut-step">${i + 1} / ${TUTORIAL.length}</div>
          <div>${step.t}</div>
          <div class="tut-row">
            <button type="button" data-a="skip">${step.last ? "" : "SKIP"}</button>
            <button type="button" class="primary" data-a="next">${step.last ? "LET'S GO ▶" : "NEXT ▶"}</button>
          </div>`;
        const skipBtn = box.querySelector('[data-a="skip"]');
        if (step.last) skipBtn.style.visibility = "hidden";
        skipBtn.onclick = done;
        box.querySelector('[data-a="next"]').onclick = () => { SFX.select(); i++; i < TUTORIAL.length ? show() : done(); };

        if (target) {
          target.scrollIntoView({ block: "center" });
          requestAnimationFrame(() => {
            const b = target.getBoundingClientRect(), pad = 6;
            Object.assign(spot.style, {
              display: "block", left: b.left - pad + "px", top: b.top - pad + "px",
              width: b.width + pad * 2 + "px", height: b.height + pad * 2 + "px"
            });
            const targetInTopHalf = b.top + b.height / 2 < window.innerHeight / 2;
            box.style.top = targetInTopHalf ? "" : "16px";
            box.style.bottom = targetInTopHalf ? "16px" : "";
          });
        } else {
          Object.assign(spot.style, { display: "block", left: "50%", top: "50%", width: "0px", height: "0px" });
          box.style.top = "50%"; box.style.bottom = "";
          box.style.transform = "translate(-50%, -50%)";
          return;
        }
        box.style.transform = "translateX(-50%)";
      }

      function done() {
        shield.remove(); spot.remove(); box.remove();
        window.scrollTo(0, 0);
        resolve();
      }

      show();
    });
  }

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------
  function shouldPlay() {
    try {
      if (new URLSearchParams(location.search).has("intro")) return true;
      return localStorage.getItem(SEEN_KEY) !== "1";
    } catch (e) { return true; }
  }

  // renderBoard: draws the game UI so the tutorial has something to point at.
  async function run(renderBoard) {
    const { tutorial } = await runCutscene();
    if (tutorial) {
      if (typeof renderBoard === "function") renderBoard();
      await runTutorial();
    }
  }

  function addReplayButton() {
    const b = el("button", { class: "replay-intro", type: "button" }, "▶ Replay intro & tutorial");
    b.addEventListener("click", () => {
      if (confirm("Replaying the intro restarts your current run. Continue?")) {
        location.href = location.pathname + "?intro=1";
      }
    });
    document.body.append(b);
  }

  window.Intro = { run, shouldPlay, runCutscene, runTutorial, addReplayButton, SCENES };
})();
;

// ── game.js ──
// game.js — day loop, buying/selling, listings, shop shelves, and all UI.
// Market + rumors: js/market.js · rent, debt, shop, rips, Grail: js/progress.js + js/rules.js

// ---------------------------------------------------------------------------
// Setup
// ---------------------------------------------------------------------------
// ?seed=abc123 replays an exact market (see seedForRun in progress.js).
function seedFromUrl() {
  try { return new URLSearchParams(location.search).get("seed"); } catch (e) { return null; }
}
let market = TCGMarket.create(seedFromUrl());
const products = market.products;
const buyLocations = market.buyLocations;
const sellLocations = market.sellLocations;
const WEEKDAYS = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

// Every place the player can go. slug drives <body data-place> for theming.
const PLACES = [
  { id: "Local Game Store", short: "Game Store",  kind: "buy",    slug: "lgs",         note: "Steady stock" },
  { id: "Cost-Mart",        short: "Cost-Mart",   kind: "buy",    slug: "costmart",    note: "Cheaper, thin shelves" },
  { id: "eCommerce Store",  short: "eComm",       kind: "buy",    slug: "ecom",        note: "Wild prices, ships in 3 days" },
  { id: "The Marketplace",  short: "Marketplace", kind: "sell",   slug: "marketplace", note: "Open daily. Low-end boxes flip for a profit" },
  { id: "TCG Convention",   short: "Convention",  kind: "sell",   slug: "convention",  note: "Sat & Sun only. Swingiest prices, moves hardest on news" },
  { id: "Online Store",     short: "Online",      kind: "online", slug: "online",      note: "List at your price, 13% fee" },
  { id: "Your Shop",        short: "Your Shop",   kind: "shop",   slug: "shop",        note: "Stock your shelves, set prices" }
];
const placeOf = id => PLACES.find(p => p.id === id);

let state = {
  day: 1,
  money: TCGRules.RULES.startCash,
  location: "Local Game Store",
  inventory: {},
  rumor: "No news yet...",
  deliveryQueue: [],
  onlineListings: [],   // { product, price, quantity, days }
  shopShelf: [],        // same shape, sold from your own shop
};
products.forEach(p => (state.inventory[p] = 0));
let gameStats = { totalBought: 0, totalSold: 0 };

const $ = id => document.getElementById(id);
const money = n => "$" + Math.round(n).toLocaleString();
const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const jsArg = s => `'${String(s).replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;

// ---------------------------------------------------------------------------
// Toasts + notice modals
// ---------------------------------------------------------------------------
function showNotification(message, type = "info") {
  const box = $("toasts");
  if (!box) return;
  const t = document.createElement("div");
  t.className = "toast" + (type === "error" ? " error" : "");
  t.innerHTML = message;
  box.appendChild(t);
  while (box.children.length > 3) box.firstChild.remove();
  setTimeout(() => t.remove(), type === "error" ? 3500 : 2800);
}

// Modals queue so a rent notice never hides a shop/grail moment.
const modalQueue = [];
let modalOpen = false;
function showModalNotification(message, title = "", onClose) {
  if (modalOpen) { modalQueue.push([message, title, onClose]); return; }
  modalOpen = true;
  let wrap = $("modal-container");
  if (!wrap) {
    wrap = document.createElement("div");
    wrap.id = "modal-container";
    document.body.appendChild(wrap);
  }
  wrap.innerHTML = `<div class="notice-modal" role="dialog" aria-modal="true">
      ${title ? `<h3>${title}</h3>` : ""}<div>${message}</div>
      <button type="button" class="btn primary ok">OK</button></div>`;
  wrap.style.display = "flex";
  wrap.querySelector(".ok").onclick = () => {
    wrap.style.display = "none";
    wrap.innerHTML = "";
    modalOpen = false;
    if (typeof onClose === "function") onClose();
    if (modalQueue.length) showModalNotification(...modalQueue.shift());
  };
}

// ---------------------------------------------------------------------------
// Buying, selling, travel
// ---------------------------------------------------------------------------
function buy(product, silent) {
  if (state.runOver) return false;
  const loc = state.location;
  const price = market.price(loc, product);
  if (price == null) { if (!silent) showNotification(`${loc} is closed today.`, "error"); return false; }
  if (market.stock(loc, product) <= 0) { if (!silent) showNotification("Sold out here.", "error"); return false; }
  if (state.money < price) { if (!silent) showNotification("Not enough cash.", "error"); return false; }
  const r = market.buy(loc, product);
  if (!r.ok) return false;
  state.money -= price;
  trackBuy(product, price);
  gameStats.totalBought++;
  if (r.arrivesDay > state.day) state.deliveryQueue.push({ product, quantity: 1, arrivalDay: r.arrivesDay });
  else state.inventory[product]++;
  if (!silent) {
    showNotification(r.arrivesDay > state.day
      ? `Bought ${product} for ${money(price)}. Arrives Day ${r.arrivesDay}.`
      : `Bought ${product} for ${money(price)}.`);
    render();
  }
  return price;
}
function buyMax(product) {
  let n = 0, spent = 0, p;
  while ((p = buy(product, true))) { n++; spent += p; }
  if (n) showNotification(`Bought ${n}× ${product} for ${money(spent)}.`);
  else buy(product); // explains why not
  render();
}

function sell(product, silent) {
  if (state.runOver) return false;
  if (!market.isOpen(state.location)) { if (!silent) showNotification(`${state.location} is closed today.`, "error"); return false; }
  if (!(state.inventory[product] > 0)) { if (!silent) showNotification("You don't have any.", "error"); return false; }
  const { price } = market.sell(state.location, product);
  state.money += price;
  state.inventory[product]--;
  trackSell(product, price);
  gameStats.totalSold++;
  if (!silent) { showNotification(`Sold ${product} for ${money(price)}.`); render(); }
  return price;
}
function sellAll(product) {
  let n = 0, got = 0, p;
  while ((p = sell(product, true))) { n++; got += p; }
  if (n) showNotification(`Sold ${n}× ${product} for ${money(got)}.`);
  else sell(product);
  render();
}

function travel(id) {
  if (state.runOver) return;
  const pl = placeOf(id);
  if (pl.kind === "shop" && !state.shopOpen) {
    state.location = id;
  } else {
    state.location = id;
    if ((pl.kind === "sell") && !market.isOpen(id)) showNotification(`${pl.short} is closed today. It runs Sat & Sun.`, "error");
  }
  render();
}

// ---------------------------------------------------------------------------
// Online listings + your shop's shelves (same mechanics, different odds)
// ---------------------------------------------------------------------------
const venues = {
  online: { list: () => state.onlineListings, cfg: () => undefined, fee: 0.13, title: "ONLINE STORE", verb: "LIST", noun: "listing" },
  shop:   { list: () => state.shopShelf, cfg: () => TCGRules.RULES.shelf, fee: 0, title: "YOUR SHELVES", verb: "SHELVE", noun: "shelf spot" }
};

function addListing(kind) {
  const v = venues[kind];
  const product = $("ls-product").value;
  const price = Math.round(parseFloat($("ls-price").value));
  const qty = parseInt($("ls-qty").value, 10);
  if (!product || !(price > 0) || !(qty > 0)) return showNotification("Pick a box, a price and a quantity.", "error");
  if ((state.inventory[product] || 0) < qty) return showNotification(`You only have ${state.inventory[product] || 0}.`, "error");
  state.inventory[product] -= qty;
  const existing = v.list().find(l => l.product === product && l.price === price);
  if (existing) existing.quantity += qty;
  else v.list().push({ product, price, quantity: qty, days: 0 });
  showNotification(`${v.verb === "LIST" ? "Listed" : "Shelved"} ${qty}× ${product} at ${money(price)}.`);
  render();
  openListingsSheet(kind);
}
function saveListing(kind, i) {
  const l = venues[kind].list()[i];
  if (!l) return;
  const price = Math.round(parseFloat($(`ls-p-${i}`).value));
  const qty = parseInt($(`ls-q-${i}`).value, 10);
  if (!(price > 0) || !(qty >= 0)) return showNotification("Enter a price and quantity.", "error");
  const diff = qty - l.quantity;
  if (diff > 0 && (state.inventory[l.product] || 0) < diff) return showNotification(`You only have ${state.inventory[l.product] || 0} more.`, "error");
  state.inventory[l.product] -= diff;
  l.quantity = qty;
  if (price !== l.price) { l.price = price; l.days = 0; }
  if (l.quantity === 0) venues[kind].list().splice(i, 1);
  showNotification("Saved.");
  render();
  openListingsSheet(kind);
}
function pullListing(kind, i) {
  const l = venues[kind].list()[i];
  if (!l) return;
  state.inventory[l.product] += l.quantity;
  venues[kind].list().splice(i, 1);
  showNotification(`Pulled ${l.quantity}× ${l.product} back to your stash.`);
  render();
  openListingsSheet(kind);
}
// Runs each new day for both venues.
function processListings(kind) {
  const v = venues[kind], list = v.list(), sales = [];
  for (let i = list.length - 1; i >= 0; i--) {
    const l = list[i];
    l.days = (l.days || 0) + 1;
    const r = market.listingSales(l.product, l.price, l.quantity, v.cfg());
    if (r.sold > 0) {
      const payout = r.sold * r.payoutEach;
      state.money += payout;
      gameStats.totalSold += r.sold;
      for (let k = 0; k < r.sold; k++) trackSell(l.product, r.payoutEach);
      l.quantity -= r.sold;
      sales.push(`${r.sold}× ${l.product} +${money(payout)}`);
      if (l.quantity <= 0) list.splice(i, 1);
    }
  }
  if (sales.length) showNotification(`${kind === "shop" ? "🏪 Shop sold" : "💻 Online sold"}: ${sales.join(", ")}`);
}

// ---------------------------------------------------------------------------
// Next day
// ---------------------------------------------------------------------------
function nextDay() {
  if (state.runOver) return;
  closeSheet();
  state.netWorthHistory.push(Math.round(netWorth()));
  if (!state.shopOpen && state.day >= TCGRules.RULES.mainDays) { state.day++; checkRunEnd(); return; }

  state.day++;
  market.nextDay();

  const arrived = [];
  state.deliveryQueue = state.deliveryQueue.filter(d => {
    if (d.arrivalDay <= state.day) { state.inventory[d.product] += d.quantity; arrived.push(d.product); return false; }
    return true;
  });
  if (arrived.length) showNotification(`📦 Delivered: ${arrived.length} box${arrived.length > 1 ? "es" : ""}.`);

  economyTick().forEach(msg => showNotification(msg, msg.includes("short") ? "error" : "info"));
  if (checkRunEnd()) return;

  processListings("online");
  if (state.shopOpen) processListings("shop");

  const news = market.headlines();
  state.rumor = news.length ? news.join("\n") : "No news today...";
  if (placeOf(state.location).kind === "sell" && !market.isOpen(state.location)) {
    showNotification(`${placeOf(state.location).short} is closed today.`, "error");
  }
  render();
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------
function totalBoxes() {
  return products.reduce((a, p) => a + (state.inventory[p] || 0), 0);
}

function render() {
  const pl = placeOf(state.location);
  document.body.dataset.place = pl.slug;

  // status bar
  $("tb-day").textContent = `DAY ${state.day} · ${WEEKDAYS[state.day % 7]}`;
  $("tb-cash").textContent = money(state.money);
  const bits = [`${totalBoxes()} BOX${totalBoxes() === 1 ? "" : "ES"}`];
  if (state.debt > 0) bits.push(`OWE ${money(state.debt)}`);
  if (state.shopOpen) {
    bits.push(state.grailBox ? "🏆 GRAIL" : `GRAIL HUNT: ${state.boxesRipped} RIPPED`);
  } else {
    const r = TCGRules.nextRent(state.day);
    const due = TCGRules.rentDue(state.day);
    bits.push(due ? `RENT PAID TODAY` : `RENT ${money(r.amount)} D${r.day}`);
    bits.push(state.money >= TCGRules.RULES.lease && !state.debt ? "SHOP READY!" : `GOAL ${money(TCGRules.RULES.lease)}`);
  }
  $("tb-summary").textContent = bits.join(" · ");

  renderPlaces();
  renderCounter();
  $("rumor").textContent = state.rumor;
  $("next-day").disabled = !!state.runOver;
}

function renderPlaces() {
  const group = (label, kinds) => `<div class="places-group"><h3>${label}</h3>${PLACES.filter(p => kinds.includes(p.kind)).map(p => {
    const closed = p.kind === "sell" && !market.isOpen(p.id);
    const locked = p.kind === "shop" && !state.shopOpen;
    const extra = locked ? "Locked" : closed ? "Closed today" : p.kind === "online" && state.onlineListings.length ? `${state.onlineListings.length} listed`
      : p.kind === "shop" && state.shopShelf.length ? `${state.shopShelf.reduce((a, l) => a + l.quantity, 0)} on shelves`
      : market.mysteryBox && p.kind === "buy" && market.mysteryBox(p.id) ? "📦 Mystery box" : "";
    return `<button type="button" class="place${p.id === state.location ? " here" : ""}${locked ? " locked" : ""}" data-place="${p.slug}" onclick="travel(${jsArg(p.id)})">${esc(p.short)}${extra ? `<small>${extra}</small>` : ""}</button>`;
  }).join("")}</div>`;
  $("places").innerHTML = group("BUY", ["buy"]) + group("SELL", ["sell", "online", "shop"]);
}

function renderCounter() {
  const pl = placeOf(state.location);
  $("here").textContent = pl.id.toUpperCase();
  let note = pl.note;
  if (pl.kind === "sell" && !market.isOpen(pl.id)) note = "CLOSED TODAY. Open Sat & Sun.";
  $("here-note").textContent = note;
  const body = $("counter-body");

  if (pl.kind === "buy" || pl.kind === "sell") {
    const closed = !market.isOpen(pl.id);
    if (closed) { body.innerHTML = `<p class="empty">Closed today. The Convention runs Saturday and Sunday.<br><br>Try The Marketplace, or list online.</p>`; return; }
    const rows = products.map(p => {
      const own = state.inventory[p] || 0;
      const price = market.price(pl.id, p);
      if (pl.kind === "buy") {
        const stock = market.stock(pl.id, p);
        return `<tr><td class="nm">${esc(p)}${own ? `<small>You have ${own}</small>` : ""}</td>
          <td class="pr">${money(price)}<small>${stock} left</small></td>
          <td class="act"><button type="button" class="btn tiny primary" onclick="buy(${jsArg(p)})" ${stock > 0 ? "" : "disabled"}>BUY</button><button type="button" class="btn tiny" onclick="buyMax(${jsArg(p)})" ${stock > 0 ? "" : "disabled"}>MAX</button></td></tr>`;
      }
      return `<tr><td class="nm">${esc(p)}<small>You have ${own}</small></td>
        <td class="pr">${money(price)}</td>
        <td class="act"><button type="button" class="btn tiny primary" onclick="sell(${jsArg(p)})" ${own ? "" : "disabled"}>SELL</button><button type="button" class="btn tiny" onclick="sellAll(${jsArg(p)})" ${own ? "" : "disabled"}>ALL</button></td></tr>`;
    }).join("");
    let mystery = "";
    if (pl.kind === "buy") {
      const mp = market.mysteryBox(pl.id);
      if (mp) mystery = `<tr class="mystery"><td class="nm">📦 Mystery Box<small>Unlabeled. Could be anything.</small></td><td class="pr">${money(mp)}<small>1 left</small></td><td class="act"><button type="button" class="btn tiny primary" onclick="buyMystery()">OPEN</button></td></tr>`;
    }
    body.innerHTML = `<table class="mk">${rows}${mystery}</table>`;
    return;
  }

  if (pl.kind === "online") {
    const list = state.onlineListings;
    body.innerHTML = (list.length
      ? `<table class="mk">${list.map(l => `<tr><td class="nm">${esc(l.product)}<small>${l.days} day${l.days === 1 ? "" : "s"} listed</small></td><td class="pr">${money(l.price)}<small>×${l.quantity}</small></td></tr>`).join("")}</table>`
      : `<p class="empty">No listings yet. List boxes at your own price and they sell over the next few days, minus a 13% fee. Price near market and they move fast.</p>`)
      + `<button type="button" class="btn primary wide" onclick="openListingsSheet('online')">MANAGE LISTINGS</button>`;
    return;
  }

  // Your Shop
  if (!state.shopOpen) {
    const ready = state.money >= TCGRules.RULES.lease && !state.debt;
    body.innerHTML = `<p class="empty">This could be yours.<br><br>Lease: ${money(TCGRules.RULES.lease)} cash, no debt. Open it and rent stops, walk-ins buy every day, and you can stock your own shelves.<br><br>${ready ? "You're ready." : `You have ${money(state.money)}${state.debt ? ` and owe ${money(state.debt)}` : ""}.`}</p>
      <button type="button" class="btn primary wide" onclick="openShop()" ${ready ? "" : "disabled"}>OPEN SHOP (${money(TCGRules.RULES.lease)})</button>`;
    return;
  }
  const shelf = state.shopShelf;
  body.innerHTML = (shelf.length
    ? `<table class="mk">${shelf.map(l => `<tr><td class="nm">${esc(l.product)}<small>on shelf ${l.days} day${l.days === 1 ? "" : "s"}</small></td><td class="pr">${money(l.price)}<small>×${l.quantity}</small></td></tr>`).join("")}</table>`
    : `<p class="empty">Empty shelves. Stock boxes from your stash and set your price. No fees, and customers walk in every day.</p>`)
    + `<button type="button" class="btn primary wide" onclick="openListingsSheet('shop')">STOCK SHELVES</button>`;
}

// ---------------------------------------------------------------------------
// Sheets (overlays)
// ---------------------------------------------------------------------------
function openSheet(title, html) {
  $("sheet-title").textContent = title;
  $("sheet-body").innerHTML = html;
  $("sheet").hidden = false;
}
function closeSheet() { const s = $("sheet"); if (s) s.hidden = true; }
document.addEventListener("keydown", e => { if (e.key === "Escape") closeSheet(); });
document.addEventListener("click", e => { if (e.target && e.target.id === "sheet") closeSheet(); });

// "YOUR STUFF": everything the status bar summarizes.
function openStuffSheet() {
  const R = TCGRules.RULES;
  const onTheWay = p => state.deliveryQueue.filter(d => d.product === p).reduce((a, d) => a + d.quantity, 0);
  const listed = (list, p) => list.filter(l => l.product === p).reduce((a, l) => a + l.quantity, 0);
  const avg = p => { const c = state.costBasis && state.costBasis[p]; return c && c.qty > 0 ? money(c.total / c.qty) : "—"; };

  let goal;
  if (state.shopOpen) {
    goal = `<p>🏪 Shop opened Day ${state.shopDay}. No more rent.</p>
      <p>${state.grailBox ? `🏆 You pulled ${R.grailName} on box #${state.grailBox}.` : `🏆 Grail hunt: ${state.boxesRipped} boxes ripped, ${state.godPacks} god pack${state.godPacks === 1 ? "" : "s"}.`}</p>`;
  } else {
    const r = TCGRules.nextRent(state.day);
    const ready = state.money >= R.lease && !state.debt;
    goal = `<div class="kv"><span>Next rent</span><span>${money(r.amount)} on Day ${r.day}</span></div>
      <div class="kv"><span>Shop lease</span><span>${money(R.lease)} by Day ${R.mainDays}</span></div>
      <button type="button" class="btn primary wide" onclick="openShop(); closeSheet();" ${ready ? "" : "disabled"}>OPEN SHOP</button>`;
  }

  const rows = products.map(p => {
    const own = state.inventory[p] || 0, way = onTheWay(p), inList = listed(state.onlineListings, p) + listed(state.shopShelf, p);
    return `<tr><td>${esc(p)}${way ? `<br><small>+${way} on the way</small>` : ""}${inList ? `<br><small>${inList} listed</small>` : ""}</td>
      <td class="num">${own}</td><td class="num">${avg(p)}</td>
      <td class="num"><button type="button" class="btn tiny" onclick="ripBox(${jsArg(p)}); openStuffSheet();" ${own && !state.runOver ? "" : "disabled"}>RIP</button></td></tr>`;
  }).join("");

  openSheet("YOUR STUFF", `
    <div class="sheet-section">
      <div class="kv"><span>Cash</span><strong>${money(state.money)}</strong></div>
      <div class="kv"><span>Debt (${R.debtRate * 100}%/day)</span><span>${money(state.debt || 0)}</span></div>
      <div class="kv"><span>Net worth</span><span>${money(netWorth())}</span></div>
      <div class="btn-row">
        <button type="button" class="btn" onclick="payDebt(); openStuffSheet();" ${state.debt > 0 && state.money > 0 ? "" : "disabled"}>PAY OFF DEBT</button>
        <button type="button" class="btn" onclick="borrow(500); openStuffSheet();" ${(state.debt || 0) < R.borrowLimit - 50 && !state.runOver ? "" : "disabled"}>BORROW $500</button>
      </div>
      <p class="hint">The loan shark lends up to ${money(R.borrowLimit)}. Owe more than ${money(R.evictAt)} and you're evicted.</p>
    </div>
    <div class="sheet-section"><h3>${state.shopOpen ? "YOUR SHOP" : "RENT & SHOP GOAL"}</h3>${goal}</div>
    <div class="sheet-section"><h3>YOUR BOXES</h3>
      <table class="inv"><tr><th>Box</th><th class="num">Have</th><th class="num">Avg paid</th><th class="num"></th></tr>${rows}</table>
      <p class="hint">RIP opens a box: you get the singles' value back (usually less than you paid) and a shot at ${R.grailName}.</p>
    </div>
    <div class="sheet-section">
      <div class="btn-row">
        <button type="button" class="btn" onclick="openOddsSheet()">ODDS & RULES</button>
        <button type="button" class="btn" onclick="replayIntro()">REPLAY INTRO</button>
      </div>
      ${window.GAME_HOME ? `<p class="hint"><a href="${esc(window.GAME_HOME.url)}" style="color:inherit">${esc(window.GAME_HOME.label)} ↗</a></p>` : ""}
    </div>`);
}

function openListingsSheet(kind) {
  const v = venues[kind];
  const owned = products.filter(p => (state.inventory[p] || 0) > 0);
  const ref = p => market.price("The Marketplace", p);
  const form = owned.length ? `
    <div class="form-grid">
      <label class="full">BOX
        <select id="ls-product" onchange="lsPrefill('${kind}')">${owned.map(p => `<option value="${esc(p)}">${esc(p)} (have ${state.inventory[p]})</option>`).join("")}</select></label>
      <label>PRICE $<input id="ls-price" type="number" inputmode="numeric" min="1" step="1"></label>
      <label>QTY<input id="ls-qty" type="number" inputmode="numeric" min="1" step="1"></label>
    </div>
    <p class="hint" id="ls-hint"></p>
    <button type="button" class="btn primary wide" onclick="addListing('${kind}')">${v.verb}</button>`
    : `<p class="empty">Nothing in your stash to ${kind === "shop" ? "shelve" : "list"}. Buy some boxes first.</p>`;

  const list = v.list();
  const current = list.length ? `<table class="inv"><tr><th>Box</th><th class="num">Price</th><th class="num">Qty</th><th class="num">Days</th><th></th></tr>
    ${list.map((l, i) => `<tr><td>${esc(l.product)}</td>
      <td class="num"><input id="ls-p-${i}" type="number" inputmode="numeric" value="${l.price}"></td>
      <td class="num"><input id="ls-q-${i}" class="qty" type="number" inputmode="numeric" value="${l.quantity}"></td>
      <td class="num">${l.days}</td>
      <td class="num"><button type="button" class="btn tiny primary" onclick="saveListing('${kind}', ${i})">SAVE</button><br><button type="button" class="btn tiny" style="margin-top:3px" onclick="pullListing('${kind}', ${i})">PULL</button></td></tr>`).join("")}</table>
    <p class="hint">Change price or quantity and hit SAVE. Quantity 0 or PULL sends boxes back to your stash.</p>`
    : `<p class="empty">No ${v.noun}s yet.</p>`;

  openSheet(v.title, `
    <div class="sheet-section"><h3>ADD</h3>${form}</div>
    <div class="sheet-section"><h3>${kind === "shop" ? "ON YOUR SHELVES" : "YOUR LISTINGS"}</h3>${current}</div>
    <div class="sheet-section"><p class="hint">${kind === "shop"
      ? "No fees. Priced at market, most boxes sell within a day or two. Every 10% over market cuts the odds."
      : "13% platform fee. Priced at market, most boxes sell within a few days. Every 10% over market cuts the odds a lot."}</p></div>`);
  if (owned.length) lsPrefill(kind);
}
function lsPrefill(kind) {
  const p = $("ls-product").value;
  const ref = market.price("The Marketplace", p);
  $("ls-price").value = Math.round(ref * (kind === "shop" ? 1.12 : 1.1));
  $("ls-qty").value = state.inventory[p] || 1;
  $("ls-hint").textContent = `The Marketplace pays ${money(ref)} for ${p} today.`;
}

function openOddsSheet() {
  const R = TCGRules.RULES;
  const pct = x => (x * 100).toFixed(x < 0.01 ? 1 : 0) + "%";
  openSheet("ODDS & RULES", `
    <div class="sheet-section"><h3>RIPPING A BOX</h3>
      ${R.rip.map(([c, lo, hi], i) => `<div class="kv"><span>${["Bricked", "Decent", "Nice hits", "Monster box"][i]}</span><span>${pct(c)} · ${lo}–${hi}× paid</span></div>`).join("")}
      <div class="kv"><span>God pack</span><span>1 in ${Math.round(1 / R.godPackChance)} · ${R.godPackCashBack[0]}–${R.godPackCashBack[1]}×</span></div>
      <div class="kv"><span>${R.grailName}</span><span>1 in ${Math.round(R.grailDollarsPerPercent * 100 / 200)} per $200 box</span></div>
      <p class="hint">Pricier boxes give better Grail odds. A god pack multiplies that box's Grail odds by ${R.godPackGrailBoost}.</p></div>
    <div class="sheet-section"><h3>MYSTERY BOX</h3>
      ${R.mystery.map(([c, name]) => `<div class="kv"><span>${{ junk: "Junk", decent: "Decent", big: "Jackpot", god: "God pack", grail: R.grailName }[name]}</span><span>${pct(c)}</span></div>`).join("")}</div>
    <div class="sheet-section"><h3>MONEY</h3>
      <p>Rent every ${R.rentEvery} days: ${R.rentStepAfter ? `${R.rent.map(money).join(", ")}, then +${money(R.rentStepAfter)}/week` : `${money(R.rent[0])}, every week`}.</p>
      <p>Debt grows ${R.debtRate * 100}% a day. Evicted at ${money(R.evictAt)}.</p>
      <p>Shop lease: ${money(R.lease)} by Day ${R.mainDays}.</p></div>`);
}

function replayIntro() {
  if (confirm("Replaying the intro restarts your current run. Continue?")) location.href = location.pathname + "?intro=1";
}

// ---------------------------------------------------------------------------
// Start / restart
// ---------------------------------------------------------------------------
function playAgain() {
  $("leaderboard-modal").style.display = "none";
  playFree = true; // the Daily Market is one shot; replays are free play
  initializeGame();
}

function initializeGame() {
  gameStats = { totalBought: 0, totalSold: 0 };
  Object.assign(state, {
    day: 1, location: "Local Game Store", money: TCGRules.RULES.startCash,
    inventory: {}, deliveryQueue: [], onlineListings: [], shopShelf: []
  });
  resetProgress();
  products.forEach(p => (state.inventory[p] = 0));

  const run = seedForRun();
  market = TCGMarket.create(run.seed, {
    mysteryChance: TCGRules.RULES.mysteryChancePerDay,
    mysteryPrice: TCGRules.RULES.mysteryPrice
  });
  state.seed = market.seed;
  state.runLabel = run.label;
  const news = market.headlines();
  state.rumor = news.length ? news.join("\n") : "No news yet...";
  render();
  showModalNotification(
    `<p><strong>${run.label}</strong></p>
     <p>${money(TCGRules.RULES.startCash)}. ${TCGRules.RULES.mainDays} days. Raise ${money(TCGRules.RULES.lease)} and open your own card shop.</p>
     <p>Rent is due every 7 days. Watch the Feed.</p>`, "THE CARDBOARD FLIP");
}

window.onload = async () => {
  resetProgress(); // so the board the tutorial points at shows real numbers
  render();
  if (window.Intro && Intro.shouldPlay()) {
    try { await Intro.run(render); } catch (e) { console.error("Intro failed, starting game anyway:", e); }
  }
  initializeGame();
};
;

// ── progress.js ──
// progress.js — rent & debt, the shop goal, ripping, mystery boxes,
// the Grail post-game, and the two share moments.
//
// Loaded after game.js; uses its globals (state, market, render, products,
// showNotification, showModalNotification). All numbers live in js/rules.js.

const { RULES } = TCGRules;
const LAUNCH_DAY = "2026-09-29"; // Daily Market #1

// ---------------------------------------------------------------------------
// Run setup
// ---------------------------------------------------------------------------
function todayKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function dailyNumber(key = todayKey()) {
  return Math.round((new Date(key + "T12:00:00") - new Date(LAUNCH_DAY + "T12:00:00")) / 86400000) + 1;
}

// First run of a page load = today's Daily Market. "Play again" = free play.
// ?seed=xyz = a friend's challenge market.
let playFree = false;
function seedForRun() {
  const fromUrl = seedFromUrl();
  if (fromUrl) return { seed: fromUrl, label: `Challenge "${fromUrl}"` };
  if (!playFree) { const k = todayKey(); return { seed: "daily-" + k, label: `Daily Market #${dailyNumber(k)}` }; }
  const s = Math.random().toString(36).slice(2, 8);
  return { seed: s, label: `Free Play (${s})` };
}

function resetProgress() {
  Object.assign(state, {
    debt: 0,
    shopOpen: false, shopDay: null,
    grailDay: null, grailBox: null, grailFrom: null,
    boxesRipped: 0, godPacks: 0, ripSpent: 0,
    netWorthHistory: [],
    costBasis: {},          // product -> { qty, total }
    bestFlip: null,         // { product, profit }
    evicted: false, runOver: false,
    shopMomentShown: false
  });
}

// ---------------------------------------------------------------------------
// Money helpers
// ---------------------------------------------------------------------------
function holdingsValue() {
  let v = 0;
  products.forEach(p => {
    const qty = (state.inventory[p] || 0)
      + state.deliveryQueue.filter(d => d.product === p).reduce((a, d) => a + d.quantity, 0)
      + state.onlineListings.filter(l => l.product === p).reduce((a, l) => a + l.quantity, 0)
      + (state.shopShelf || []).filter(l => l.product === p).reduce((a, l) => a + l.quantity, 0);
    v += qty * market.valueNow(p) * 0.9;
  });
  return v;
}
function netWorth() { return state.money + holdingsValue() - state.debt; }
const usd = n => "$" + Math.round(n).toLocaleString();

function trackBuy(product, price) {
  const c = state.costBasis[product] || (state.costBasis[product] = { qty: 0, total: 0 });
  c.qty++; c.total += price;
}
function trackSell(product, price) {
  const c = state.costBasis[product];
  if (!c || c.qty <= 0) return;
  const avg = c.total / c.qty;
  c.qty--; c.total -= avg;
  const profit = price - avg;
  if (!state.bestFlip || profit > state.bestFlip.profit) state.bestFlip = { product, profit };
}
function removeFromBasis(product) {
  const c = state.costBasis[product];
  if (c && c.qty > 0) { c.total -= c.total / c.qty; c.qty--; }
}

// ---------------------------------------------------------------------------
// Daily tick: interest, rent (before the shop) or shop income (after)
// ---------------------------------------------------------------------------
function economyTick() {
  const msgs = [];
  if (state.debt > 0) {
    const interest = state.debt * RULES.debtRate;
    state.debt += interest;
    msgs.push(`💸 Loan shark interest: +${usd(interest)} (you owe ${usd(state.debt)})`);
  }
  if (!state.shopOpen) {
    const rent = TCGRules.rentDue(state.day);
    if (rent) {
      const paid = Math.min(state.money, rent);
      state.money -= paid;
      const short = rent - paid;
      if (short > 0) {
        state.debt += short;
        msgs.push(`🏠 Rent was ${usd(rent)}. You were ${usd(short)} short, and it went on your tab at ${RULES.debtRate * 100}% a day.`);
      } else {
        msgs.push(`🏠 Paid rent: ${usd(rent)}.`);
      }
    }
  } else {
    const [lo, hi] = RULES.shopIncome;
    const income = Math.round(lo + Math.random() * (hi - lo));
    state.money += income;
    msgs.push(`🏪 Walk-ins spent ${usd(income)} on singles and supplies.`);
  }
  if (state.debt > RULES.evictAt) state.evicted = true;
  return msgs;
}

// ---------------------------------------------------------------------------
// Player actions
// ---------------------------------------------------------------------------
function borrow(amount = 500) {
  if (state.runOver) return;
  const room = RULES.borrowLimit - state.debt;
  if (room < 50) return showNotification(`The loan shark won't go past ${usd(RULES.borrowLimit)}.`, "error");
  const amt = Math.min(amount, Math.floor(room));
  state.debt += amt; state.money += amt;
  showNotification(`Borrowed ${usd(amt)} at ${RULES.debtRate * 100}% a day. Owe: ${usd(state.debt)}`, "warning");
  render();
}
function payDebt() {
  if (state.debt <= 0) return;
  const pay = Math.min(state.money, state.debt);
  if (pay <= 0) return showNotification("No cash to pay with.", "error");
  state.money -= pay; state.debt -= pay;
  if (state.debt < 0.01) state.debt = 0;
  showNotification(state.debt ? `Paid ${usd(pay)}. Still owe ${usd(state.debt)}.` : `Paid off the loan shark. 🙏`, "success");
  render();
}

function openShop() {
  if (state.shopOpen || state.runOver) return;
  if (state.debt > 0) return showNotification("Pay off your debt before signing a lease.", "error");
  if (state.money < RULES.lease) return showNotification(`You need ${usd(RULES.lease)} cash for the lease.`, "error");
  state.money -= RULES.lease;
  state.shopOpen = true;
  state.shopDay = state.day;
  state.location = "Your Shop";
  render();
  showMoment("shop");
}

function ripBox(product) {
  if (state.runOver || !(state.inventory[product] > 0)) return;
  const value = market.valueNow(product);
  state.inventory[product]--;
  removeFromBasis(product);
  const r = TCGRules.ripBox(value);
  state.boxesRipped++;
  state.ripSpent += value;
  state.money += r.cashBack;
  if (r.god) state.godPacks++;
  gameStats.totalSold++;
  if (r.grail) return foundGrail("rip", product);
  if (r.god) {
    showModalNotification(`<p>Every pack in this ${escapeHtml(product)} box hit.</p><p>You pulled <strong>${usd(r.cashBack)}</strong> in singles.</p>`, "⚡ GOD PACK ⚡");
  } else {
    const verdict = r.cashBack >= value * 3 ? "🔥 MONSTER BOX" : r.cashBack >= value * 1.2 ? "Nice hits" : r.cashBack >= value * 0.65 ? "Decent" : "Bricked";
    showNotification(`Ripped ${product}: ${verdict}. Singles worth ${usd(r.cashBack)} (box was ~${usd(value)}). Box #${state.boxesRipped}.`, r.cashBack >= value ? "success" : "info");
  }
  render();
}

function buyMystery() {
  if (state.runOver) return;
  const price = market.mysteryBox(state.location);
  if (!price) return;
  if (state.money < price) return showNotification("Not enough cash for the mystery box.", "error");
  market.takeMysteryBox(state.location);
  state.money -= price;
  const r = TCGRules.openMystery(price);
  state.boxesRipped++;
  state.ripSpent += price;
  state.money += r.cashBack;
  if (r.god) state.godPacks++;
  if (r.grail) return foundGrail("mystery");
  const text = {
    junk: `Junk. Bulk commons and a sticker. Worth ${usd(r.cashBack)}.`,
    decent: `Not bad! Some playables worth ${usd(r.cashBack)}.`,
    big: `🔥 JACKPOT! A sealed vintage pack inside. Worth ${usd(r.cashBack)}!`,
    god: `⚡ A GOD PACK was hiding in there! ${usd(r.cashBack)} in hits!`
  }[r.outcome];
  showModalNotification(`<p>You paid ${usd(price)}.</p><p>${text}</p>`, "📦 MYSTERY BOX");
  render();
}

function foundGrail(from, product) {
  state.grailDay = state.day;
  state.grailBox = state.boxesRipped;
  state.grailFrom = from === "mystery" ? "a mystery box" : product;
  render();
  showMoment("grail");
}

// ---------------------------------------------------------------------------
// Share moments
// ---------------------------------------------------------------------------
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function trendStrip(maxDays) {
  const h = state.netWorthHistory.slice(0, maxDays);
  let prev = RULES.startCash, out = "";
  h.forEach(v => {
    out += v > prev * 1.01 ? "🟩" : v < prev * 0.99 ? "🟥" : "⬜";
    prev = v;
  });
  return out;
}
function challengeLink() {
  return `${location.origin}${location.pathname.replace(/index\.html$/, "")}?seed=${encodeURIComponent(state.seed)}`;
}

function shareText(kind) {
  const head = `THE CARDBOARD FLIP · ${state.runLabel}`;
  if (kind === "shop") {
    const lines = [
      head,
      `🏪 Opened my card shop on DAY ${state.shopDay}`,
      `💵 ${usd(RULES.startCash)} → ${usd(RULES.lease)} lease in ${state.shopDay} days`,
      trendStrip(state.shopDay)
    ];
    if (state.bestFlip && state.bestFlip.profit > 0) lines.push(`🔥 Best flip: ${state.bestFlip.product} +${usd(state.bestFlip.profit)}`);
    lines.push(challengeLink());
    return lines.join("\n");
  }
  if (kind === "grail") {
    const lines = [
      head,
      `🏆 Pulled ${RULES.grailName} on box #${state.grailBox} (Day ${state.grailDay})`,
      state.grailFrom === "a mystery box" ? "🎁 Straight out of a mystery box" : `📦 From a ${state.grailFrom} box`,
      `💸 ${usd(state.ripSpent)} chased · ${state.godPacks} god pack${state.godPacks === 1 ? "" : "s"}`
    ];
    if (!state.shopOpen) lines.push("😳 Before I even opened a shop");
    lines.push(challengeLink());
    return lines.join("\n");
  }
  // end of run
  const rank = TCGRules.rankFor({ evicted: state.evicted, shopDay: state.shopDay, grailBox: state.grailBox, netWorth: netWorth() });
  const lines = [head, `Rank: ${rank}`];
  if (state.shopDay) lines.push(`🏪 Shop opened Day ${state.shopDay}`);
  else lines.push(`🏪 Never opened the shop`);
  if (state.grailBox) lines.push(`🏆 ${RULES.grailName} on box #${state.grailBox} (Day ${state.grailDay})`);
  lines.push(`💵 Net worth: ${usd(netWorth())}`);
  lines.push(trendStrip(RULES.mainDays));
  lines.push(challengeLink());
  return lines.join("\n");
}

async function shareRun(kind) {
  const text = shareText(kind);
  try {
    if (navigator.share) { await navigator.share({ text }); return; }
  } catch (e) { if (e && e.name === "AbortError") return; }
  try {
    await navigator.clipboard.writeText(text);
    showNotification("Copied! Paste it anywhere.", "success");
  } catch (e) {
    window.prompt("Copy your result:", text);
  }
}

function momentHtml(kind) {
  const title = kind === "shop"
    ? `<p style="font-size:1.2em">🏪 You opened your own card shop on <strong>DAY ${state.shopDay}</strong>.</p>
       <p>Rent is over. Walk-ins buy every day, and you can stock your own shelves at your own prices.</p>
       <p><strong>POST-GAME:</strong> hunt for <strong>${RULES.grailName}</strong>. RIP boxes (tap MORE up top), open mystery boxes, and pray for a god pack. Keep flipping to fund it. The hunt ends when you pull it or go broke.</p>`
    : `<p style="font-size:1.2em">🏆 You pulled <strong>${RULES.grailName}</strong> on box <strong>#${state.grailBox}</strong>!</p>
       <p>${state.shopOpen ? "That's the whole game. Legend." : "Before you even opened a shop. Absolute lotto. Keep going for the shop!"}</p>`;
  return `${title}
    <pre class="share-preview">${escapeHtml(shareText(kind))}</pre>
    <button type="button" class="btn primary" onclick="shareRun('${kind}')">SHARE</button>`;
}
function showMoment(kind) {
  showModalNotification(momentHtml(kind), kind === "shop" ? "SHOP OPENED" : "GRAIL PULLED", () => {
    if (kind === "grail" && state.shopOpen) endRun("grail");
  });
}

// ---------------------------------------------------------------------------
// End of run
// ---------------------------------------------------------------------------
function checkRunEnd() {
  if (state.runOver) return true;
  if (state.evicted) { endRun("evicted"); return true; }
  if (!state.shopOpen && state.day > RULES.mainDays) { endRun("time"); return true; }
  if (state.day >= RULES.maxDays) { endRun("season"); return true; }
  return false;
}

function endRun(reason) {
  if (state.runOver) return;
  state.runOver = true;
  const why = {
    evicted: `The loan shark came to collect. You owed ${usd(state.debt)}. EVICTED.`,
    time: `Day ${RULES.mainDays} came and went without a shop.`,
    season: `The season's over.`,
    grail: `You own a card shop AND ${RULES.grailName}.`
  }[reason];
  document.getElementById("final-reason").textContent = why;
  document.getElementById("final-rank").textContent =
    TCGRules.rankFor({ evicted: state.evicted, shopDay: state.shopDay, grailBox: state.grailBox, netWorth: netWorth() });
  document.getElementById("final-money").textContent = Math.round(netWorth()).toLocaleString();
  document.getElementById("final-days").textContent = Math.max(1, state.netWorthHistory.length);
  document.getElementById("final-shop").textContent = state.shopDay ? `Day ${state.shopDay}` : "—";
  document.getElementById("final-grail").textContent = state.grailBox ? `Box #${state.grailBox}` : "—";
  document.getElementById("final-bought").textContent = gameStats.totalBought;
  document.getElementById("final-sold").textContent = gameStats.totalSold;
  document.getElementById("final-share").textContent = shareText("end");
  document.getElementById("leaderboard-modal").style.display = "flex";
}
;
